css:
.rent-receipt { font-size: 13px; }
.rent-receipt .receipt-head { display: flex; justify-content: space-between; border-bottom: 2px solid #333; margin-bottom: 16px; padding-bottom: 8px; }
.rent-receipt h2 { margin: 0; }
.rent-receipt .muted { color: #666; }
.rent-receipt th { width: 35%; }
.rent-receipt .draft { color: #c0392b; font-weight: bold; }
.rent-receipt .signature { margin-top: 60px; text-align: right; border-top: 1px solid #999; width: 200px; margin-left: auto; padding-top: 4px; }
